+                assert!(
+                    !*file_meta_resolved,
+                    "Finding B: file with changed file_meta_ipns_name (same mtime) MUST be \
+                     marked file_meta_resolved=false; got true (stale state carried over)"
+                );
+                assert_eq!(
+                    file_meta_ipns_name.as_deref(),
