+    #[test]
+    fn upsert_children_file_same_mtime_same_ipns_name_stays_resolved() {
+        let mut table = InodeTable::new();
+        let ipns = "k51same-file-ipns";
+        let mtime_ms = 5000u64;
+
+        let _file_ino = seed_resolved_file(&mut table, ipns, mtime_ms);
