+                    name: "report.txt".to_string(),
+                    file_meta_ipns_name: ipns.to_string(), // SAME pointer identity
+                    ipns_private_key_encrypted: None,
+                    created_at: 1000,
+                    modified_at: mtime_ms, // SAME mtime
